export const TRICK_KEY = "earwig";
export const TRICKS = ["cercithreat", "fanwing", "nightscuttle", "broodguard", "tegminacurl", "cerciwhip", "forficulahush"] as const;
export const HAPPY = ["densforceps", "inkforceps", "densforficula"] as const;
export type EarwigTrickKind = (typeof TRICKS)[number];
export type EarwigHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type EarwigTrick = {
  kind: EarwigTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type EarwigHappy = {
  kind: EarwigHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { densforceps: 1.70, inkforceps: 1.84, densforficula: 1.76 } as const;
export const FORFICULAHUSH_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  forficulahush: FORFICULAHUSH_HOLD + RELEASE_S,
  cercithreat: 2.48,
  fanwing: 2.42,
  nightscuttle: 2.40,
  broodguard: 2.44,
  tegminacurl: 2.38,
  cerciwhip: 2.56,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: EarwigTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "forficulahush") return 40 + roll * 26;
  if (kind === "tegminacurl" || kind === "cercithreat" || kind === "broodguard") return 12.8 + roll * 9.4;
  if (kind === "nightscuttle" || kind === "fanwing" || kind === "cerciwhip") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

